import { initializeApp } from "firebase/app";
import { getFirestore, doc, getDocFromServer } from "firebase/firestore";
import firebaseConfigData from "../firebase-applet-config.json";

// Initialize Firebase using the configuration generated by the system
const app = initializeApp({
  apiKey: firebaseConfigData.apiKey,
  authDomain: firebaseConfigData.authDomain,
  projectId: firebaseConfigData.projectId,
  storageBucket: firebaseConfigData.storageBucket,
  messagingSenderId: firebaseConfigData.messagingSenderId,
  appId: firebaseConfigData.appId
});

// Initialize Firestore with the specific database ID provided
export const db = getFirestore(app, firebaseConfigData.firestoreDatabaseId);

// Validate connection to Firestore as per the required critical guidelines
async function testConnection() {
  try {
    await getDocFromServer(doc(db, "test", "connection"));
    console.log("[Firebase] Connection validated successfully.");
  } catch (error) {
    if (error instanceof Error && error.message.includes("the client is offline")) {
      console.error("[Firebase] Connection failed: Please check your Firebase configuration or network status.");
    } else {
      console.log("[Firebase] Initialization response received (database online or empty).");
    }
  }
}

testConnection();
